import { forwardRef, useEffect, useImperativeHandle, useLayoutEffect, useMemo, useRef, useState, type ComponentProps } from "react";
import { Interactive, Sequence, continueRender, delayRender, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

// Every timing in remocn is written in frames of a 30 fps timeline: a delay
// of 12, a rise over 20, a spring fed `fps`. Read straight from Remotion,
// those numbers mean something else in a 60 fps composition: a tween runs
// twice as fast, while a spring keeps its length, so a scene does not even
// speed up evenly.
//
// These two hooks stand in for Remotion's and answer on that 30 fps timeline
// whatever rate the composition runs at. At 60 fps the frame goes 0, 0.5, 1,
// 1.5: the scene lasts the same number of seconds and every frame in between
// is a new picture. At 30 fps they return exactly what Remotion does.
//
//   const frame = useSceneFrame();
//   const { fps, width } = useSceneConfig();
//
// What a component hands back to Remotion is still counted in the
// composition's own frames: `from` and `durationInFrames` of a `<Sequence>`,
// the length of a transition. `useCompositionFrames()` converts those.

/** The frame rate remocn timings are written in. */
const SCENE_FPS = 30;

/** `useCurrentFrame()` in 30 fps frames; fractional above 30 fps. */
function useSceneFrame(): number {
  const { fps } = useVideoConfig();
  return (useCurrentFrame() * SCENE_FPS) / fps;
}

/**
 * `useVideoConfig()` on the 30 fps timeline: `fps` is 30 and
 * `durationInFrames` counts 30 fps frames. Size and the rest are untouched.
 */
function useSceneConfig(): ReturnType<typeof useVideoConfig> {
  const config = useVideoConfig();
  return useMemo(
    () => ({
      ...config,
      fps: SCENE_FPS,
      durationInFrames: (config.durationInFrames * SCENE_FPS) / config.fps,
    }),
    [config],
  );
}

/**
 * Turns a count of 30 fps frames into the composition's own, for what
 * Remotion itself reads: `<Sequence from={frames(24)}>`. Whole frames only,
 * as Remotion requires.
 */
function useCompositionFrames(): (sceneFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (sceneFrames: number) => Math.round((sceneFrames * fps) / SCENE_FPS),
    [fps],
  );
}

/**
 * The other way round: a count Remotion gives a component in the
 * composition's own frames, in 30 fps frames. A transition's presentation
 * gets its length that way (`presentationDurationInFrames`).
 */
function useSceneFrameCount(): (compositionFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (compositionFrames: number) => (compositionFrames * SCENE_FPS) / fps,
    [fps],
  );
}

// A component's schedule, kept apart from its drawing: which elements the
// animation has (an entry, a word, a finale), when each starts and how long
// it runs. The schedule is a pure function of the props, so it can be read
// without rendering anything, and a `timing` prop can move, trim or stretch
// single elements without touching the code that draws them.
//
//   // timeline.ts, next to the component
//   export const titleTimeline = defineTimeline<TitleElementId, TitleProps>(
//     ({ words = WORDS }, { length }) =>
//       words.map((word, k) => ({
//         id: `word:${k}`,
//         lane: "Words",
//         label: word,
//         start: k * 8,
//         length: 8,
//         follows: k > 0 ? `word:${k - 1}` : undefined,
//         beats: { rise: 12 },
//       })),
//   );
//
//   // index.tsx
//   const tl = useTimeline(titleTimeline, props, length, timing);
//   const word = tl.get("word:0");
//   interpolate(t, [word.start, word.start + word.beat("rise")], [0, 1]);
//
// Every number is in frames of the 30 fps scene timeline, after `delay` and
// `speed`: those still apply to the whole animation, `timing` works inside it.
// Element ids are public API: a saved `timing` refers to them, so an id once
// shipped keeps its meaning.

/** One timed part of an animation, as its schedule lays it out. */
interface TimelineElement<Id extends string = string> {
  /** Stable name a `timing` override refers to: `entry:0`, `finale`. */
  id: Id;
  /** Row the element sits on in a timeline view. */
  lane: string;
  /** What the element shows, for people reading the timeline. */
  label: string;
  /** First frame of the element. */
  start: number;
  /** Frames until the next element of the lane takes over, or the end. */
  length: number;
  /**
   * The element this one comes after. When that element's end moves, this
   * one moves with it, keeping the gap between them.
   */
  follows?: Id;
  /**
   * Named frame counts inside the element, measured from its start: how long
   * a roll takes, when a second part begins. `stretch` scales them.
   */
  beats?: Record<string, number>;
}

/** A change to one element, made from outside the component. */
interface TimingOverride {
  /** New first frame. Wins over the shift from `follows`. */
  start?: number;
  /** New length, trimming or extending the element. Wins over `stretch`. */
  length?: number;
  /** Multiplies the length and every beat: 2 plays the element half as fast. */
  stretch?: number;
  /** Stops following: the element keeps its own start when the one before moves. */
  detach?: boolean;
}

/** Overrides by element id: the `timing` prop of a component. */
type Timing<Id extends string = string> = Partial<
  Record<Id, TimingOverride>
>;

/** A component's schedule: props and the scene length in, elements out. */
type Schedule<Id extends string, Props> = (
  props: Props,
  scene: { length: number },
) => TimelineElement<Id>[];

/** An element after `timing` has been applied. */
interface ResolvedElement<Id extends string = string>
  extends TimelineElement<Id> {
  /** `start + length`. */
  end: number;
  beats: Record<string, number>;
  /** A beat by name, stretched. Throws on a name the schedule didn't set. */
  beat(name: string): number;
  /**
   * 0 → 1 over the element, or over its first `beat` frames when a beat is
   * named. Clamped on both sides.
   */
  progress(frame: number, beat?: string): number;
}

interface ResolvedTimeline<Id extends string = string> {
  /** All elements, in the order the schedule returned them. */
  elements: ResolvedElement<Id>[];
  /** An element by id. Throws on an id the schedule didn't return. */
  get(id: Id): ResolvedElement<Id>;
  /** The elements of one lane, in order. */
  lane(name: string): ResolvedElement<Id>[];
}

/** Declares a schedule. Elements come back in time order. */
function defineTimeline<Id extends string, Props>(
  schedule: Schedule<Id, Props>,
): Schedule<Id, Props> {
  return schedule;
}

/** Applies `timing` to a schedule's elements and carries the `follows` chains. */
function resolve<Id extends string>(
  elements: TimelineElement<Id>[],
  timing: Timing<Id> = {},
): ResolvedTimeline<Id> {
  const byId = new Map<Id, TimelineElement<Id>>(elements.map((e) => [e.id, e]));
  const done = new Map<Id, ResolvedElement<Id>>();
  const visiting = new Set<Id>();

  const place = (element: TimelineElement<Id>): ResolvedElement<Id> => {
    const known = done.get(element.id);
    if (known) return known;
    if (visiting.has(element.id)) {
      throw new Error(`timeline: "${element.id}" follows itself`);
    }
    visiting.add(element.id);

    const override: TimingOverride = timing[element.id] ?? {};
    const stretch = override.stretch ?? 1;
    const beats: Record<string, number> = {};
    for (const [name, frames] of Object.entries(element.beats ?? {})) {
      beats[name] = frames * stretch;
    }

    let start = element.start;
    const leader = element.follows ? byId.get(element.follows) : undefined;
    if (leader && !override.detach) {
      // The leader's end moved by this much; this element moves as far.
      start += place(leader).end - (leader.start + leader.length);
    }
    if (override.start !== undefined) start = override.start;
    const length = override.length ?? element.length * stretch;

    const beat = (name: string) => {
      const frames = beats[name];
      if (frames === undefined) {
        throw new Error(`timeline: "${element.id}" has no beat "${name}"`);
      }
      return frames;
    };
    const resolved: ResolvedElement<Id> = {
      ...element,
      start,
      length,
      end: start + length,
      beats,
      beat,
      progress: (frame, name) => {
        const span = name === undefined ? length : beat(name);
        if (span <= 0) return frame >= start ? 1 : 0;
        return Math.min(1, Math.max(0, (frame - start) / span));
      },
    };
    visiting.delete(element.id);
    done.set(element.id, resolved);
    return resolved;
  };

  const all = elements.map(place);
  return {
    elements: all,
    get: (id) => {
      const element = done.get(id);
      if (!element) throw new Error(`timeline: no element "${id}"`);
      return element;
    },
    lane: (name) => all.filter((e) => e.lane === name),
  };
}

/**
 * The component side: runs the schedule and applies `timing`, once per
 * change of its inputs. `length` is the scene length the schedule fits into,
 * in the same frames the component counts.
 */
function useTimeline<Id extends string, Props>(
  schedule: Schedule<Id, Props>,
  props: Props,
  length: number,
  timing?: Timing<Id>,
): ResolvedTimeline<Id> {
  return useMemo(
    () => resolve(schedule(props, { length }), timing),
    [schedule, props, length, timing],
  );
}

// One element per word cycle: the word hangs at the near point after the
// swap, arrives, rests readable, departs and hangs again until the next
// swap. Cycle `k` shows word `k` of the phrase, wrapping round, so the
// phrase loops for as long as the scene runs. The scene opens halfway
// through the first rest, so the first cycle starts before frame 0.
// Frames on the 30 fps scene timeline, after `speed`. The ids are public:
// a saved `timing` prop refers to them.

type RushTypeElementId = `cycle:${number}`;

interface RushTypeTimingProps {
  phrase?: string;
  restDuration?: number;
  peakHoldDuration?: number;
}

const RUSH_PHRASE = "gone before you look";
const ARRIVE_FRAMES = 7;
const LEAVE_FRAMES = 4;
const DEFAULT_REST_FRAMES = 12;
const DEFAULT_HOLD_FRAMES = 3;

/** The phrase as words; an empty phrase falls back to the reference one. */
function phraseWords(phrase: string): string[] {
  const words = phrase.trim().split(/\s+/).filter(Boolean);
  return words.length > 0 ? words : RUSH_PHRASE.split(" ");
}

/** Frames from one word swap to the next. */
function cycleLengthOf(
  restDuration = DEFAULT_REST_FRAMES,
  peakHoldDuration = DEFAULT_HOLD_FRAMES,
): number {
  return (
    ARRIVE_FRAMES +
    LEAVE_FRAMES +
    Math.max(restDuration, 1) +
    Math.max(peakHoldDuration, 0)
  );
}

// `cycle:<k>` starts on a word swap. Its beats are the phases in order:
// `hold` (half the near-point hang, on each side of the swap), `arrive`,
// `rest`, `leave`. The cycles form a chain and run past the end of the
// scene, so the shutter samples around the last frame still land in one.
const rushTypeTimeline = defineTimeline<
  RushTypeElementId,
  RushTypeTimingProps
>(
  (
    {
      phrase = RUSH_PHRASE,
      restDuration = DEFAULT_REST_FRAMES,
      peakHoldDuration = DEFAULT_HOLD_FRAMES,
    },
    { length },
  ) => {
    const words = phraseWords(phrase);
    const safeRest = Math.max(restDuration, 1);
    const safeHold = Math.max(peakHoldDuration, 0);
    const halfHold = safeHold / 2;
    const cycleLength = cycleLengthOf(safeRest, safeHold);
    const startOffset = halfHold + ARRIVE_FRAMES + safeRest / 2;
    const count = Math.max(
      1,
      Math.ceil((Math.max(length, 0) + startOffset) / cycleLength) + 1,
    );
    return Array.from({ length: count }, (_, k) => ({
      id: `cycle:${k}` as const,
      lane: "Words",
      label: words[k % words.length],
      start: k * cycleLength - startOffset,
      length: cycleLength,
      follows: k > 0 ? (`cycle:${k - 1}` as const) : undefined,
      beats: {
        hold: halfHold,
        arrive: ARRIVE_FRAMES,
        rest: safeRest,
        leave: LEAVE_FRAMES,
      },
    }));
  },
);

interface RushTypeProps {
  /** A short phrase. One whitespace-delimited word is shown per cycle. */
  phrase?: string;
  /** Cap height of the resting word in composition pixels. */
  fontSize?: number;
  fontFamily?: string;
  fontWeight?: number;
  color?: string;
  backgroundColor?: string;
  /** Authored vertical scale at the blast before perspective is applied. */
  verticalStretch?: number;
  /** 0 removes channel separation, 1 is the reference look, 2 exaggerates it. */
  chromaticSpread?: number;
  /** Readable resting phase, in frames. */
  restDuration?: number;
  /** Total near-point hang around the word swap, in frames. */
  peakHoldDuration?: number;
  /** Global playback multiplier. */
  speed?: number;
  /**
   * Moves, trims or stretches single word cycles, by the ids in
   * `./timeline`. Frames on the scene timeline, after `speed`.
   */
  timing?: Timing<RushTypeElementId>;
  className?: string;
}

type RushTypePhase = "hang" | "arrive" | "rest" | "depart";

interface RushTypeFrameState {
  phase: RushTypePhase;
  wordIndex: number;
  beforeWordIndex: number;
  afterWordIndex: number;
  cycle: number;
  motion: number;
  isResting: boolean;
  swapAmount: number;
  shutterRatios: [number, number, number];
  thinAmount: number;
  bloomAmount: number;
  crtAmount: number;
  groundAmount: number;
}

const rushTypeDefaultPhrase = RUSH_PHRASE;

const SHUTTER_SECONDS = 0.04;
const SMEAR_GAIN = 1.6;
const SAMPLES = 28;
const SHUTTER_SHAPE = 0.85;
const ROLL_U = 0.38;
const LAG_U = 0.55;
const THIN = 0.55;
const BLOOM_GAIN = 0.5;
const BLOOM_SPREAD = 3.2;
const BLOOM_BIAS = 3.5;
const SPEED_GAIN = 0.95;
const EXPOSURE = 1.75;
const HORIZONTAL_STRETCH = 1.57;
const FOCAL = 1;
const ORBIT_DEPTH = 0.42;
const ORBIT_RISE = 0.16;
const ORBIT_YAW = 0.55;
const ORBIT_YAW_LAG = 0.6;
const ORBIT_PITCH = 0.26;
const ORBIT_PITCH_LAG = -0.9;
const ORBIT_HANG_ARC = 0.9;
const PIVOT_FRAC = 0.07;
const CRT_GAIN = 1;
const CRT_PITCH = 5;
const CRT_MASK = 0.16;
const CRT_SCAN_PITCH = 3;
const CRT_SCAN = 0.12;
const CRT_BEAM = 0.7;
const CRT_HUM = 0.035;
const CRT_HUM_SPEED = 0.14;
const GROUND_SPEED = 0.028;
const GLOW_SPREAD = 2.6;
const GLOW_MIN = 0.34;
const GLOW_MAX_Y = 1.2;
const SWAP_SPREAD = 0.35;
const SWAP_FLASH = 0.5;

const FALL = [1, 0.557, 0.121, 0.049, 0.014, 0];
const RISE = [0, 0.08, 0.8, 1];
const ORBIT_IN = [0, 0.5, 0.82, 0.95, 1, 1];
const ORBIT_OUT = [0, 0.05, 0.14, 0.38, 1];
const DRIFT_DIRECTION = [-1, 0.7, -0.45, 1];
const SWING_ARC = Math.PI - ORBIT_HANG_ARC;

function parseHexColor(
  value: string,
  fallback: readonly [number, number, number],
): [number, number, number] {
  const hex = value.trim().replace(/^#/, "");
  const expanded =
    hex.length === 3 ? hex.replace(/./g, (char) => char + char) : hex;
  if (!/^[0-9a-f]{6}$/i.test(expanded)) {
    return [fallback[0], fallback[1], fallback[2]];
  }
  return [
    Number.parseInt(expanded.slice(0, 2), 16) / 255,
    Number.parseInt(expanded.slice(2, 4), 16) / 255,
    Number.parseInt(expanded.slice(4, 6), 16) / 255,
  ];
}

function positiveModulo(value: number, modulus: number): number {
  return ((value % modulus) + modulus) % modulus;
}

function sampleTable(table: readonly number[], progress: number): number {
  const last = table.length - 1;
  const x = Math.min(Math.max(progress, 0), 1) * last;
  const index = Math.min(Math.floor(x), last - 1);
  return table[index] + (table[index + 1] - table[index]) * (x - index);
}

const normalizeRushTypePhrase = phraseWords;

const getRushTypeCycleLength = cycleLengthOf;

function getRushTypeDuration({
  phrase = rushTypeDefaultPhrase,
  restDuration = DEFAULT_REST_FRAMES,
  peakHoldDuration = DEFAULT_HOLD_FRAMES,
}: Pick<
  RushTypeProps,
  "phrase" | "restDuration" | "peakHoldDuration"
> = {}): number {
  return Math.round(
    normalizeRushTypePhrase(phrase).length *
      getRushTypeCycleLength(restDuration, peakHoldDuration),
  );
}

const rushTypeLength = getRushTypeDuration();

function getRushTypeShutterRatios(
  chromaticSpread = 1,
): [number, number, number] {
  const spread = Math.max(chromaticSpread, 0);
  return [0.62 ** spread, 1, 0.34 ** spread];
}

interface TimelinePose {
  phase: RushTypePhase;
  p: number;
  psi: number;
  cycle: number;
  wordIndex: number;
}

type Cycle = ResolvedElement<RushTypeElementId>;

/** The cycle playing at `frame`: the last one that has started. */
function cycleAt(frame: number, cycles: Cycle[]): number {
  let cycle = 0;
  for (let k = 1; k < cycles.length; k++) {
    if (cycles[k].start <= frame) cycle = k;
  }
  return cycle;
}

function getTimelinePose(
  frame: number,
  cycles: Cycle[],
  wordCount: number,
): TimelinePose {
  const safeWordCount = Math.max(Math.floor(wordCount), 1);
  const cycle = cycleAt(frame, cycles);
  const e = cycles[cycle];
  const halfHold = e.beat("hold");
  const arriveFrames = e.beat("arrive");
  const leaveFrames = e.beat("leave");
  const arriveEnd = halfHold + arriveFrames;
  const restEnd = arriveEnd + e.beat("rest");
  const leaveEnd = restEnd + leaveFrames;
  const tau = frame - e.start;
  const wordIndex = positiveModulo(cycle, safeWordCount);

  if (tau < halfHold) {
    return {
      phase: "hang",
      p: 1,
      psi: ORBIT_HANG_ARC * (tau / Math.max(halfHold, 1e-6)),
      cycle,
      wordIndex,
    };
  }

  if (tau < arriveEnd) {
    const progress = (tau - halfHold) / arriveFrames;
    return {
      phase: "arrive",
      p: sampleTable(FALL, progress),
      psi: ORBIT_HANG_ARC + SWING_ARC * sampleTable(ORBIT_IN, progress),
      cycle,
      wordIndex,
    };
  }

  if (tau < restEnd) {
    return { phase: "rest", p: 0, psi: Math.PI, cycle, wordIndex };
  }

  if (tau < leaveEnd) {
    const progress = (tau - restEnd) / leaveFrames;
    return {
      phase: "depart",
      p: sampleTable(RISE, progress),
      psi: Math.PI + SWING_ARC * sampleTable(ORBIT_OUT, progress),
      cycle,
      wordIndex,
    };
  }

  // Clamped for a cycle trimmed past its hang; untouched it stays below 1.
  const progress = Math.min(1, (tau - leaveEnd) / Math.max(halfHold, 1e-6));
  return {
    phase: "hang",
    p: 1,
    psi: 2 * Math.PI - ORBIT_HANG_ARC * (1 - progress),
    cycle,
    wordIndex,
  };
}

interface ComputedFrame {
  before: TimelinePose;
  here: TimelinePose;
  after: TimelinePose;
  swapU: number;
  swapAmount: number;
  shutterRatios: [number, number, number];
}

function computeFrame({
  frame,
  fps,
  wordCount,
  chromaticSpread,
  cycles,
}: {
  frame: number;
  fps: number;
  wordCount: number;
  chromaticSpread: number;
  cycles: Cycle[];
}): ComputedFrame {
  const shutterFrames = SHUTTER_SECONDS * Math.max(fps, 1);
  const halfShutter = shutterFrames / 2;
  const before = getTimelinePose(frame - halfShutter, cycles, wordCount);
  const here = getTimelinePose(frame, cycles, wordCount);
  const after = getTimelinePose(frame + halfShutter, cycles, wordCount);
  // Distance to the nearer word swap: this cycle's start or its end.
  const current = cycles[here.cycle];
  const boundaryDistance = Math.min(frame - current.start, current.end - frame);
  const crossesSwap = wordCount > 1 && after.cycle > before.cycle;
  const swapU = crossesSwap
    ? (cycles[after.cycle].start - frame) / shutterFrames
    : 2;
  const swapAmount =
    wordCount > 1
      ? Math.max(0, 1 - (2 * boundaryDistance) ** 2 / shutterFrames ** 2)
      : 0;

  return {
    before,
    here,
    after,
    swapU,
    swapAmount,
    shutterRatios: getRushTypeShutterRatios(chromaticSpread),
  };
}

/**
 * The state at `frame`. `timeline` is the resolved schedule; by default the
 * untouched one, long enough to reach `frame`.
 */
function getRushTypeFrameState(
  {
    frame,
    fps = 30,
    phrase = rushTypeDefaultPhrase,
    restDuration = DEFAULT_REST_FRAMES,
    peakHoldDuration = DEFAULT_HOLD_FRAMES,
    chromaticSpread = 1,
    speed = 1,
  }: {
    frame: number;
    fps?: number;
  } & Pick<
    RushTypeProps,
    "phrase" | "restDuration" | "peakHoldDuration" | "chromaticSpread" | "speed"
  >,
  timeline?: ResolvedTimeline<RushTypeElementId>,
): RushTypeFrameState {
  const words = normalizeRushTypePhrase(phrase);
  const effectiveFrame = frame * Math.max(speed, 0);
  const tl =
    timeline ??
    resolve(
      rushTypeTimeline(
        { phrase, restDuration, peakHoldDuration },
        { length: effectiveFrame + 1 },
      ),
    );
  const computed = computeFrame({
    frame: effectiveFrame,
    fps,
    wordCount: words.length,
    chromaticSpread,
    cycles: tl.elements,
  });
  const motion = computed.here.p;

  return {
    phase: computed.here.phase,
    wordIndex: computed.here.wordIndex,
    beforeWordIndex: computed.before.wordIndex,
    afterWordIndex: computed.after.wordIndex,
    cycle: computed.here.cycle,
    motion,
    isResting:
      computed.here.phase === "rest" &&
      computed.before.p === 0 &&
      computed.after.p === 0,
    swapAmount: computed.swapAmount,
    shutterRatios: computed.shutterRatios,
    thinAmount: THIN * motion,
    bloomAmount: BLOOM_GAIN * motion,
    crtAmount: CRT_GAIN * motion,
    groundAmount: GROUND_SPEED * motion,
  };
}

function orbitTurn(psi: number, amplitude: number, lag: number): number {
  const pin = Math.sin(lag);
  return (amplitude * (Math.sin(psi - lag) - pin)) / (1 + Math.abs(pin));
}

const VERTEX_SHADER = `
attribute vec2 aPos;
varying vec2 vUv;
void main() {
  vUv = aPos * 0.5 + 0.5;
  gl_Position = vec4(aPos, 0.0, 1.0);
}
`;

const FRAGMENT_SHADER = `
precision highp float;
varying vec2 vUv;

uniform sampler2D uText;
uniform vec2 uRes;
uniform vec2 uHalfPx;
uniform float uAtlasRows;
uniform float uSx;
uniform vec3 uSyQ;
uniform float uCenterY;
uniform float uSwapU;
uniform float uHalfA;
uniform float uHalfB;
uniform vec3 uK;
uniform vec2 uSwapScl;
uniform float uShape;
uniform float uRoll;
uniform float uLag;
uniform float uThin;
uniform float uBloom;
uniform float uGain;
uniform float uExp;
uniform float uFocal;
uniform vec3 uPos;
uniform vec4 uRot;
uniform float uCrt;
uniform float uTime;
uniform vec4 uGlow;
uniform float uGlowAmp;
uniform vec3 uColor;
uniform vec3 uBg;

#define SAMPLES ${SAMPLES}
#define BLOOM_TAPS 4
#define BLOOM_SPREAD ${BLOOM_SPREAD.toFixed(3)}
#define BLOOM_BIAS ${BLOOM_BIAS.toFixed(3)}
#define TAU 6.2831853
#define CRT_PITCH ${CRT_PITCH.toFixed(3)}
#define CRT_MASK ${CRT_MASK.toFixed(4)}
#define CRT_SCAN_PITCH ${CRT_SCAN_PITCH.toFixed(3)}
#define CRT_SCAN ${CRT_SCAN.toFixed(4)}
#define CRT_BEAM ${CRT_BEAM.toFixed(4)}
#define CRT_HUM ${CRT_HUM.toFixed(4)}
#define CRT_HUM_SPEED ${CRT_HUM_SPEED.toFixed(4)}

vec2 atlasUv(float sy, float halfIdx, vec2 wordPoint, out float inside) {
  float sx = max(uSx, 1e-4);
  float sv = max(abs(sy), 1e-4);
  vec2 q = vec2(
    (wordPoint.x / sx + uHalfPx.x * 0.5) / uHalfPx.x,
    (wordPoint.y / sv + uHalfPx.y * 0.5) / uHalfPx.y
  );
  inside = step(0.0, q.x) * step(q.x, 1.0) * step(0.0, q.y) * step(q.y, 1.0);
  return vec2(
    clamp(q.x, 0.0, 1.0),
    (clamp(q.y, 0.0, 1.0) + halfIdx) / uAtlasRows
  );
}

float tap(float sy, float halfIdx, vec2 wordPoint, float front) {
  float inside;
  vec2 texturePoint = atlasUv(sy, halfIdx, wordPoint, inside);
  float value = texture2D(uText, texturePoint).r * inside * front;
  return value * mix(1.0, value, uThin);
}

float tapBlur(float sy, float halfIdx, vec2 wordPoint, float front) {
  float inside;
  vec2 texturePoint = atlasUv(sy, halfIdx, wordPoint, inside);
  return texture2D(uText, texturePoint, BLOOM_BIAS).r * inside * front;
}

void main() {
  vec2 pixel = vUv * uRes;
  vec2 center = vec2(uRes.x * 0.5, uRes.y * uCenterY);
  vec2 screenPoint = pixel - center;

  float sinYaw = uRot.x;
  float cosYaw = uRot.y;
  float sinPitch = uRot.z;
  float cosPitch = uRot.w;
  float a1 = -(screenPoint.x * sinYaw + uFocal * cosYaw);
  float b1 = sinPitch * (screenPoint.x * cosYaw - uFocal * sinYaw);
  float c1 = uFocal * uPos.x - screenPoint.x * uPos.z;
  float a2 = -screenPoint.y * sinYaw;
  float b2 = screenPoint.y * sinPitch * cosYaw - uFocal * cosPitch;
  float c2 = uFocal * uPos.y - screenPoint.y * uPos.z;
  float determinant = a1 * b2 - a2 * b1;
  float inverse = 1.0 / (abs(determinant) < 1e-4 ? 1e-4 : determinant);
  float a = (c1 * b2 - c2 * b1) * inverse;
  float b = (a1 * c2 - a2 * c1) * inverse;
  float cameraZ = uPos.z - a * sinYaw + b * sinPitch * cosYaw;
  vec2 wordPoint = vec2(a, b);
  float front = step(uFocal * 0.05, cameraZ);
  vec3 accumulated = vec3(0.0);

  if (abs(uSyQ.y) + abs(uSyQ.z) < 1e-5) {
    accumulated = vec3(tap(uSyQ.x, uHalfA, wordPoint, front));
  } else {
    float offset =
      uLag * (wordPoint.x / uRes.x) - uRoll * (screenPoint.y / uRes.y);
    float weightSum = 0.0;

    for (int i = 0; i < SAMPLES; i++) {
      float u = float(i) / float(SAMPLES - 1) - 0.5;
      float weight = 1.0 - uShape * abs(u) * 2.0;
      weightSum += weight;
      float shiftedU = u + offset;
      vec3 shutterU = shiftedU * uK;
      vec3 sy = uSyQ.x + uSyQ.y * shutterU + uSyQ.z * shutterU * shutterU;
      accumulated.r += weight * tap(
        sy.r * (shutterU.r < uSwapU ? uSwapScl.x : uSwapScl.y),
        shutterU.r < uSwapU ? uHalfA : uHalfB,
        wordPoint,
        front
      );
      accumulated.g += weight * tap(
        sy.g * (shutterU.g < uSwapU ? uSwapScl.x : uSwapScl.y),
        shutterU.g < uSwapU ? uHalfA : uHalfB,
        wordPoint,
        front
      );
      accumulated.b += weight * tap(
        sy.b * (shutterU.b < uSwapU ? uSwapScl.x : uSwapScl.y),
        shutterU.b < uSwapU ? uHalfA : uHalfB,
        wordPoint,
        front
      );
    }

    accumulated /= max(weightSum, 1e-4);

    vec3 halo = vec3(0.0);
    for (int j = 0; j < BLOOM_TAPS; j++) {
      float u =
        (float(j) / float(BLOOM_TAPS - 1) - 0.5) * BLOOM_SPREAD + offset;
      vec3 shutterU = u * uK;
      vec3 sy = uSyQ.x + uSyQ.y * shutterU + uSyQ.z * shutterU * shutterU;
      halo.r += tapBlur(
        sy.r * (shutterU.r < uSwapU ? uSwapScl.x : uSwapScl.y),
        shutterU.r < uSwapU ? uHalfA : uHalfB,
        wordPoint,
        front
      );
      halo.g += tapBlur(
        sy.g * (shutterU.g < uSwapU ? uSwapScl.x : uSwapScl.y),
        shutterU.g < uSwapU ? uHalfA : uHalfB,
        wordPoint,
        front
      );
      halo.b += tapBlur(
        sy.b * (shutterU.b < uSwapU ? uSwapScl.x : uSwapScl.y),
        shutterU.b < uSwapU ? uHalfA : uHalfB,
        wordPoint,
        front
      );
    }
    accumulated += halo * (uBloom / float(BLOOM_TAPS));
    accumulated *= uGain;
  }

  accumulated =
    (1.0 - exp(-accumulated * uExp)) / (1.0 - exp(-uExp));

  vec2 glowDistance =
    (pixel - uGlow.xy) / max(uGlow.zw, vec2(1.0));
  float ground =
    uGlowAmp * (1.0 - smoothstep(0.0, 1.0, length(glowDistance)));
  accumulated += ground * (1.0 - accumulated);

  if (uCrt > 0.0) {
    float luminance = max(max(accumulated.r, accumulated.g), accumulated.b);
    vec3 maskWave = 0.5 + 0.5 * cos(
      TAU * (pixel.x / CRT_PITCH - vec3(0.0, 0.33333, 0.66667))
    );
    vec3 mask = mix(vec3(1.0), maskWave * 2.0, CRT_MASK * uCrt);
    float scanWave = 0.5 + 0.5 * cos(TAU * pixel.y / CRT_SCAN_PITCH);
    float scan =
      1.0 - CRT_SCAN * uCrt * (1.0 - CRT_BEAM * luminance) * (1.0 - scanWave);
    float bar = 0.5 + 0.5 * cos(
      TAU * (pixel.y / uRes.y - uTime * CRT_HUM_SPEED)
    );
    float hum = 1.0 + CRT_HUM * uCrt * (bar * 2.0 - 1.0);
    accumulated *= mask * scan * hum;
  }

  gl_FragColor = vec4(uBg + (uColor - uBg) * accumulated, 1.0);
}
`;

const UNIFORM_NAMES = [
  "uText",
  "uRes",
  "uHalfPx",
  "uAtlasRows",
  "uSx",
  "uSyQ",
  "uCenterY",
  "uSwapU",
  "uHalfA",
  "uHalfB",
  "uK",
  "uSwapScl",
  "uShape",
  "uRoll",
  "uLag",
  "uThin",
  "uBloom",
  "uGain",
  "uExp",
  "uFocal",
  "uPos",
  "uRot",
  "uCrt",
  "uTime",
  "uGlow",
  "uGlowAmp",
  "uColor",
  "uBg",
] as const;

interface GlState {
  gl: WebGLRenderingContext;
  program: WebGLProgram;
  buffer: WebGLBuffer;
  texture: WebGLTexture;
  uniforms: Record<(typeof UNIFORM_NAMES)[number], WebGLUniformLocation | null>;
  atlasWidth: number;
  halfHeight: number;
  textureCapHeight: number;
  maxTextureSize: number;
  scratch: HTMLCanvasElement;
  atlasKey: string;
  atlasRows: number;
  wordHalfWidths: number[];
  wordHalfWidth: number;
}

function compileShader(
  gl: WebGLRenderingContext,
  type: number,
  source: string,
): WebGLShader {
  const shader = gl.createShader(type);
  if (!shader) throw new Error("RushTypeBase could not create a WebGL shader");
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
    const message = gl.getShaderInfoLog(shader) ?? "Unknown shader error";
    gl.deleteShader(shader);
    throw new Error(`RushTypeBase shader compilation failed: ${message}`);
  }
  return shader;
}

function createGlState(canvas: HTMLCanvasElement): GlState | null {
  const gl = canvas.getContext("webgl", {
    alpha: false,
    antialias: false,
    depth: false,
    stencil: false,
    preserveDrawingBuffer: false,
    powerPreference: "high-performance",
  });
  if (!gl) return null;

  const vertex = compileShader(gl, gl.VERTEX_SHADER, VERTEX_SHADER);
  const fragment = compileShader(gl, gl.FRAGMENT_SHADER, FRAGMENT_SHADER);
  const program = gl.createProgram();
  if (!program) throw new Error("RushTypeBase could not create a WebGL program");
  gl.attachShader(program, vertex);
  gl.attachShader(program, fragment);
  gl.bindAttribLocation(program, 0, "aPos");
  gl.linkProgram(program);
  gl.deleteShader(vertex);
  gl.deleteShader(fragment);
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    const message = gl.getProgramInfoLog(program) ?? "Unknown link error";
    gl.deleteProgram(program);
    throw new Error(`RushTypeBase shader linking failed: ${message}`);
  }

  const buffer = gl.createBuffer();
  const texture = gl.createTexture();
  if (!buffer || !texture) {
    throw new Error("RushTypeBase could not allocate WebGL resources");
  }
  gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
  gl.bufferData(
    gl.ARRAY_BUFFER,
    new Float32Array([-1, -1, 3, -1, -1, 3]),
    gl.STATIC_DRAW,
  );

  const atlasWidth = canvas.width >= 1800 ? 4096 : 2048;
  const halfHeight = atlasWidth / 4;
  const textureCapHeight = Math.round(halfHeight * 0.64);
  gl.bindTexture(gl.TEXTURE_2D, texture);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
  gl.texParameteri(
    gl.TEXTURE_2D,
    gl.TEXTURE_MIN_FILTER,
    gl.LINEAR_MIPMAP_LINEAR,
  );
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);

  const scratch = document.createElement("canvas");
  scratch.width = atlasWidth;
  scratch.height = halfHeight;
  const uniforms = Object.fromEntries(
    UNIFORM_NAMES.map((name) => [name, gl.getUniformLocation(program, name)]),
  ) as GlState["uniforms"];
  gl.clearColor(0, 0, 0, 1);

  return {
    gl,
    program,
    buffer,
    texture,
    uniforms,
    atlasWidth,
    halfHeight,
    textureCapHeight,
    maxTextureSize: gl.getParameter(gl.MAX_TEXTURE_SIZE) as number,
    scratch,
    atlasKey: "",
    atlasRows: 2,
    wordHalfWidths: [],
    wordHalfWidth: 1,
  };
}

function resolveFontFamily(fontFamily: string): string {
  if (typeof document === "undefined") return fontFamily;
  const probe = document.createElement("span");
  probe.style.cssText =
    "position:absolute;visibility:hidden;pointer-events:none";
  probe.style.fontFamily = fontFamily;
  probe.textContent = "Ag";
  document.body.appendChild(probe);
  const resolved = getComputedStyle(probe).fontFamily;
  probe.remove();
  return resolved || fontFamily;
}

function rasterWord(
  state: GlState,
  word: string,
  row: number,
  fontFamily: string,
  fontWeight: number,
): number {
  const context = state.scratch.getContext("2d");
  if (!context) return 1;
  context.fillStyle = "#000";
  context.fillRect(0, 0, state.atlasWidth, state.halfHeight);

  let rasterSize = state.textureCapHeight * 1.4;
  context.font = `${fontWeight} ${rasterSize}px ${fontFamily}`;
  const capHeight =
    context.measureText("H").actualBoundingBoxAscent || rasterSize * 0.72;
  rasterSize *= state.textureCapHeight / capHeight;
  context.font = `${fontWeight} ${rasterSize}px ${fontFamily}`;

  const maxWidth = state.atlasWidth * 0.92;
  const measured = context.measureText(word).width;
  if (measured > maxWidth) {
    rasterSize *= maxWidth / measured;
    context.font = `${fontWeight} ${rasterSize}px ${fontFamily}`;
  }

  context.fillStyle = "#fff";
  context.textAlign = "center";
  context.textBaseline = "alphabetic";
  context.fillText(
    word,
    state.atlasWidth / 2,
    state.halfHeight / 2 + state.textureCapHeight / 2,
  );
  const halfWidth = context.measureText(word).width / 2;

  const { gl } = state;
  gl.bindTexture(gl.TEXTURE_2D, state.texture);
  gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, true);
  gl.texSubImage2D(
    gl.TEXTURE_2D,
    0,
    0,
    row * state.halfHeight,
    gl.RGBA,
    gl.UNSIGNED_BYTE,
    state.scratch,
  );
  gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, false);
  return halfWidth;
}

function nextPowerOfTwo(value: number): number {
  return 2 ** Math.ceil(Math.log2(Math.max(value, 2)));
}

function getRushTypePhraseAtlasRows({
  wordCount,
  rowHeight,
  maxTextureSize,
}: {
  wordCount: number;
  rowHeight: number;
  maxTextureSize: number;
}): number | null {
  const rows = nextPowerOfTwo(wordCount);
  return rowHeight * rows <= maxTextureSize ? rows : null;
}

function allocateAtlas(state: GlState, rows: number): void {
  const { gl } = state;
  gl.bindTexture(gl.TEXTURE_2D, state.texture);
  gl.texImage2D(
    gl.TEXTURE_2D,
    0,
    gl.RGBA,
    state.atlasWidth,
    state.halfHeight * rows,
    0,
    gl.RGBA,
    gl.UNSIGNED_BYTE,
    null,
  );
  state.atlasRows = rows;
}

function updateAtlas(
  state: GlState,
  words: string[],
  firstWordIndex: number,
  secondWordIndex: number,
  fontFamily: string,
  fontWeight: number,
): { firstRow: number; secondRow: number } {
  const phraseRows = getRushTypePhraseAtlasRows({
    wordCount: words.length,
    rowHeight: state.halfHeight,
    maxTextureSize: state.maxTextureSize,
  });

  if (phraseRows !== null) {
    const atlasKey = `phrase\u0000${fontFamily}\u0000${fontWeight}\u0000${words.join("\u0000")}`;
    if (state.atlasKey !== atlasKey) {
      allocateAtlas(state, phraseRows);
      state.wordHalfWidths = words.map((word, row) =>
        rasterWord(state, word, row, fontFamily, fontWeight),
      );
      state.gl.generateMipmap(state.gl.TEXTURE_2D);
      state.atlasKey = atlasKey;
    }
    state.wordHalfWidth = Math.max(
      state.wordHalfWidths[firstWordIndex] ?? 1,
      state.wordHalfWidths[secondWordIndex] ?? 1,
    );
    return { firstRow: firstWordIndex, secondRow: secondWordIndex };
  }

  const firstWord = words[firstWordIndex] ?? words[0];
  const secondWord = words[secondWordIndex] ?? words[0];
  const atlasKey = `pair\u0000${fontFamily}\u0000${fontWeight}\u0000${firstWord}\u0000${secondWord}`;
  if (state.atlasKey !== atlasKey) {
    allocateAtlas(state, 2);
    const firstWidth = rasterWord(state, firstWord, 0, fontFamily, fontWeight);
    const secondWidth = rasterWord(
      state,
      secondWord,
      1,
      fontFamily,
      fontWeight,
    );
    state.gl.generateMipmap(state.gl.TEXTURE_2D);
    state.wordHalfWidths = [firstWidth, secondWidth];
    state.atlasKey = atlasKey;
  }
  state.wordHalfWidth = Math.max(...state.wordHalfWidths, 1);
  return { firstRow: 0, secondRow: 1 };
}

function destroyGlState(state: GlState): void {
  const { gl } = state;
  gl.deleteProgram(state.program);
  gl.deleteBuffer(state.buffer);
  gl.deleteTexture(state.texture);
}

function drawRushType({
  state,
  computed,
  words,
  fontSize,
  fontFamily,
  fontWeight,
  verticalStretch,
  textColor,
  backgroundColor,
  frame,
  fps,
}: {
  state: GlState;
  computed: ComputedFrame;
  words: string[];
  fontSize: number;
  fontFamily: string;
  fontWeight: number;
  verticalStretch: number;
  textColor: [number, number, number];
  backgroundColor: [number, number, number];
  frame: number;
  fps: number;
}): void {
  const { gl, uniforms } = state;
  const { firstRow, secondRow } = updateAtlas(
    state,
    words,
    computed.before.wordIndex,
    computed.after.wordIndex,
    fontFamily,
    fontWeight,
  );

  const unit = Math.max(fontSize, 1) / state.textureCapHeight;
  const scaleY = (pose: TimelinePose) =>
    unit * (1 + pose.p * (Math.max(verticalStretch, 1) - 1));
  const scaleBefore = scaleY(computed.before);
  const scaleCurrent = scaleY(computed.here);
  const scaleAfter = scaleY(computed.after);
  const quadraticA = scaleCurrent;
  const quadraticC = 2 * (scaleAfter + scaleBefore - 2 * scaleCurrent);
  const tangent = scaleAfter - scaleBefore;
  const peakSmear = SMEAR_GAIN * computed.here.p * scaleCurrent;
  const magnitude = Math.sqrt(tangent * tangent + peakSmear * peakSmear);
  const quadraticB = tangent < 0 ? -magnitude : magnitude;
  const scaleX = unit * (1 + computed.here.p * (HORIZONTAL_STRETCH - 1));

  const direction =
    DRIFT_DIRECTION[
      positiveModulo(computed.here.cycle, DRIFT_DIRECTION.length)
    ] ?? 1;
  const psi = computed.here.psi * Math.sign(direction || 1);
  const orbitAmplitude = Math.abs(direction);
  const focal =
    state.scratch.height > 0 ? state.gl.drawingBufferHeight * FOCAL : 1;
  const z = focal * (1 - ORBIT_DEPTH * (1 + Math.cos(psi)) * 0.5);
  const x = 0;
  const y = focal * ORBIT_RISE * orbitAmplitude * Math.sin(psi);
  const yaw = orbitTurn(psi, ORBIT_YAW, ORBIT_YAW_LAG);
  const pitch = orbitTurn(psi, ORBIT_PITCH, ORBIT_PITCH_LAG);
  const pivot = PIVOT_FRAC * computed.here.p;
  const perspective = focal / z;
  const glowX = gl.drawingBufferWidth / 2 + (focal * x) / z;
  const glowY = gl.drawingBufferHeight * (0.5 + pivot) + (focal * y) / z;
  const wordWidth = state.wordHalfWidth * scaleX * perspective;
  const wordHeight = state.textureCapHeight * scaleCurrent * perspective;

  gl.viewport(0, 0, gl.drawingBufferWidth, gl.drawingBufferHeight);
  // biome-ignore lint/correctness/useHookAtTopLevel: gl.useProgram is a WebGL method, not a React hook
  gl.useProgram(state.program);
  gl.bindBuffer(gl.ARRAY_BUFFER, state.buffer);
  gl.enableVertexAttribArray(0);
  gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);
  gl.activeTexture(gl.TEXTURE0);
  gl.bindTexture(gl.TEXTURE_2D, state.texture);
  gl.uniform1i(uniforms.uText, 0);
  gl.uniform2f(uniforms.uRes, gl.drawingBufferWidth, gl.drawingBufferHeight);
  gl.uniform2f(uniforms.uHalfPx, state.atlasWidth, state.halfHeight);
  gl.uniform1f(uniforms.uAtlasRows, state.atlasRows);
  gl.uniform1f(uniforms.uSx, scaleX);
  gl.uniform3f(uniforms.uSyQ, quadraticA, quadraticB, quadraticC);
  gl.uniform1f(uniforms.uCenterY, 0.5 + pivot);
  gl.uniform1f(uniforms.uSwapU, computed.swapU);
  gl.uniform1f(uniforms.uHalfA, firstRow);
  gl.uniform1f(uniforms.uHalfB, secondRow);
  gl.uniform3f(
    uniforms.uK,
    computed.shutterRatios[0],
    computed.shutterRatios[1],
    computed.shutterRatios[2],
  );
  gl.uniform2f(
    uniforms.uSwapScl,
    1 + SWAP_SPREAD * computed.swapAmount,
    1 - SWAP_SPREAD * computed.swapAmount,
  );
  gl.uniform1f(uniforms.uShape, SHUTTER_SHAPE);
  gl.uniform1f(uniforms.uRoll, ROLL_U);
  gl.uniform1f(uniforms.uLag, LAG_U);
  gl.uniform1f(uniforms.uThin, THIN * computed.here.p);
  gl.uniform1f(uniforms.uBloom, BLOOM_GAIN * computed.here.p);
  gl.uniform1f(
    uniforms.uGain,
    (1 + SPEED_GAIN * computed.here.p) * (1 + SWAP_FLASH * computed.swapAmount),
  );
  gl.uniform1f(uniforms.uExp, EXPOSURE);
  gl.uniform1f(uniforms.uFocal, focal);
  gl.uniform3f(uniforms.uPos, x, y, z);
  gl.uniform4f(
    uniforms.uRot,
    Math.sin(yaw),
    Math.cos(yaw),
    Math.sin(pitch),
    Math.cos(pitch),
  );
  gl.uniform1f(uniforms.uCrt, CRT_GAIN * computed.here.p);
  gl.uniform1f(uniforms.uTime, frame / Math.max(fps, 1));
  gl.uniform4f(
    uniforms.uGlow,
    glowX,
    glowY,
    Math.max(wordWidth * GLOW_SPREAD, gl.drawingBufferWidth * GLOW_MIN),
    Math.min(
      Math.max(wordHeight * GLOW_SPREAD, gl.drawingBufferHeight * GLOW_MIN),
      gl.drawingBufferHeight * GLOW_MAX_Y,
    ),
  );
  gl.uniform1f(uniforms.uGlowAmp, GROUND_SPEED * computed.here.p);
  gl.uniform3f(uniforms.uColor, textColor[0], textColor[1], textColor[2]);
  gl.uniform3f(
    uniforms.uBg,
    backgroundColor[0],
    backgroundColor[1],
    backgroundColor[2],
  );
  gl.clearColor(backgroundColor[0], backgroundColor[1], backgroundColor[2], 1);
  gl.clear(gl.COLOR_BUFFER_BIT);
  gl.drawArrays(gl.TRIANGLES, 0, 3);
}

function RushTypeBase(props: RushTypeProps) {
  const {
    phrase = rushTypeDefaultPhrase,
    fontSize = 68,
    fontFamily = "Arial, Helvetica, sans-serif",
    fontWeight = 400,
    color = "#ffffff",
    backgroundColor = "#000000",
    verticalStretch = 7,
    chromaticSpread = 1,
    speed = 1,
    timing,
    className,
  } = props;
  const frame = useSceneFrame();
  const { fps, width, height, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    rushTypeTimeline,
    props,
    durationInFrames * Math.max(speed, 0),
    timing,
  );
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const stateRef = useRef<GlState | null>(null);
  const [fontReady, setFontReady] = useState(false);
  const [webGlFailed, setWebGlFailed] = useState(false);
  const [renderHandle] = useState(() => delayRender("rush-type: first frame"));
  const continuedRef = useRef(false);
  const words = useMemo(() => normalizeRushTypePhrase(phrase), [phrase]);
  const resolvedFontFamily = useMemo(
    () => resolveFontFamily(fontFamily),
    [fontFamily],
  );
  const textColor = useMemo(() => parseHexColor(color, [1, 1, 1]), [color]);
  const frameColor = useMemo(
    () => parseHexColor(backgroundColor, [0, 0, 0]),
    [backgroundColor],
  );
  const effectiveFrame = frame * Math.max(speed, 0);
  const computed = computeFrame({
    frame: effectiveFrame,
    fps,
    wordCount: words.length,
    chromaticSpread,
    cycles: tl.elements,
  });

  useEffect(() => {
    let cancelled = false;
    setFontReady(false);
    const ready = () => {
      if (!cancelled) setFontReady(true);
    };
    if (typeof document === "undefined" || !document.fonts) {
      ready();
      return () => {
        cancelled = true;
      };
    }
    document.fonts
      .load(
        `${Number(fontWeight) || 400} ${Math.max(fontSize, 1)}px ${fontFamily}`,
      )
      .then(ready, ready);
    return () => {
      cancelled = true;
    };
  }, [fontFamily, fontSize, fontWeight]);

  useLayoutEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas || stateRef.current || webGlFailed) return;
    try {
      const state = createGlState(canvas);
      if (!state) {
        setWebGlFailed(true);
        return;
      }
      stateRef.current = state;
    } catch {
      setWebGlFailed(true);
    }
    return () => {
      if (stateRef.current) destroyGlState(stateRef.current);
      stateRef.current = null;
    };
  }, [webGlFailed]);

  useLayoutEffect(() => {
    const state = stateRef.current;
    if (!state || !fontReady) return;
    drawRushType({
      state,
      computed,
      words,
      fontSize,
      fontFamily: resolvedFontFamily,
      fontWeight: Number(fontWeight) || 400,
      verticalStretch,
      textColor,
      backgroundColor: frameColor,
      frame: effectiveFrame,
      fps,
    });
    if (!continuedRef.current) {
      continuedRef.current = true;
      continueRender(renderHandle);
    }
  }, [
    computed,
    effectiveFrame,
    fontReady,
    fontSize,
    fontWeight,
    fps,
    frameColor,
    renderHandle,
    resolvedFontFamily,
    textColor,
    verticalStretch,
    words,
  ]);

  useEffect(() => {
    if (!webGlFailed || continuedRef.current) return;
    continuedRef.current = true;
    continueRender(renderHandle);
  }, [renderHandle, webGlFailed]);

  const currentWord = words[computed.here.wordIndex] ?? words[0];

  return (
    <div
      className={className}
      role="img"
      aria-label={`${phrase}: words stretching into vertical motion blur`}
      style={{
        position: "absolute",
        inset: 0,
        overflow: "hidden",
        backgroundColor,
      }}
    >
      <canvas
        ref={canvasRef}
        width={width}
        height={height}
        style={{
          display: webGlFailed ? "none" : "block",
          width: "100%",
          height: "100%",
        }}
      />
      {webGlFailed ? (
        <div
          style={{
            position: "absolute",
            inset: 0,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            color,
            fontFamily,
            fontSize,
            fontWeight,
          }}
        >
          {currentWord}
        </div>
      ) : null}
    </div>
  );
}

