const ELEMENT_PROP_KEYS = new Set(["phrase","fontSize","fontWeight","color","backgroundColor","verticalStretch","chromaticSpread","restDuration","peakHoldDuration","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  phrase: "gone before you look",
  fontSize: 68,
  fontWeight: "400",
  color: "#ffffff",
  backgroundColor: "#000000",
  verticalStretch: 7,
  chromaticSpread: 1,
  restDuration: 12,
  peakHoldDuration: 3,
  speed: 1,
};

type RushTypeElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof RushTypeBase>;

const RushTypeInner = forwardRef<
  HTMLDivElement,
  RushTypeElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<RushType>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <RushTypeBase
          {...(componentProps as unknown as ComponentProps<typeof RushTypeBase>)}
        />
      </div>
    </Sequence>
  );
});

export const RushType = Interactive.withSchema({
  Component: RushTypeInner,
  componentName: "<RushType>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
